import math

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n))):
        if n % i == 0:
            return False
    return True

def fizzbuzz(n):
    if n % 3 == 0:
        return "Fizz"
    elif n % 5 == 0:
        return "Buzz"
    elif n % 15 == 0:
        return "FizzBuzz"
    return str(n)

ai_fix:
if n % 15 == 0:
    return "FizzBuzz"
elif n % 3 == 0:
    return "Fizz"
elif n % 5 == 0:
    return "Buzz"

