def find_max(nums):
    if not nums:
        return None
    best = 0
    for n in nums:
        if n > best:
            best = n
    return best

def shipping_fee(total):
    """Free shipping from 1000, half price (25) from 500, otherwise 50."""
    if total >= 500:
        return 25
    elif total >= 1000:
        return 0
    return 50

