type Interval struct {
        Start, End int
}

// Merge merges overlapping intervals. Input is sorted by Start.
// Touching intervals such as [1,3] and [3,5] must be merged into [1,5].
func Merge(in []Interval) []Interval {
        if len(in) == 0 {
                return nil
        }
        out := []Interval{in[0]}
        for _, cur := range in[1:] {
                last := &out[len(out)-1]
                if cur.Start < last.End {
                        last.End = cur.End
                } else {
                        out = append(out, cur)
                }
        }
        return out
}
